(
    IDLE,
    MOVING,
    COMPLETE,
    FAULT
);
END_TYPE
No implementation maybe empty string.

Need call compile_st. Need possibly formal verify. Let's do plan? User asks only JSON. We should avoid chatter? We need tool calls. No preamble maybe okay but instructions ask preamble. However final only JSON likely commentary tool calls hidden? We can say one line? User explicitly "Return ONLY a JSON object..." Means final only. Tool call preambles could violate? Better not send prose, just tool calls. But platform says before making tool calls send brief preamble. Yet user wants only final. We can perhaps not, or use no commentary. We have tool calls in commentary. Let's invoke compile.

source.declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    AtExit : BOOL;
    Jam : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Belt : BOOL;
    Complete : BOOL;
    Fault : BOOL;
END_VAR
VAR
    state : E_State := E_State.IDLE;
END_VAR

source.implementation:
IF Jam THEN
    state := E_State.FAULT;
ELSIF Reset THEN
    state := E_State.IDLE;
ELSIF state = E_State.FAULT THEN
    ;
ELSIF Stop THEN
    state := E_State.IDLE;
ELSIF state = E_State.MOVING AND AtExit THEN
    state := E_State.COMPLETE;
ELSIF state = E_State.IDLE AND Start AND NOT AtExit THEN
    state := E_State.MOVING;
END_IF

Belt := state = E_State.MOVING;
Complete := state = E_State.COMPLETE;
Fault := state = E_State.FAULT;

